package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Interval struct {
	l, r int
}

var reader *bufio.Reader
var writer *bufio.Writer

func next() int {
	res := 0
	for {
		b, err := reader.ReadByte()
		if err != nil {
			return res
		}
		if b >= '0' && b <= '9' {
			res = int(b - '0')
			break
		}
	}
	for {
		b, err := reader.ReadByte()
		if err != nil {
			return res
		}
		if b < '0' || b > '9' {
			return res
		}
		res = res*10 + int(b-'0')
	}
}

func binarySearch(list []*Interval, target int) int {
	lo, hi := 0, len(list)
	for lo < hi {
		mid := (lo + hi) / 2
		if list[mid].l < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo < len(list) && list[lo].l == target {
		return lo
	}
	return ^lo
}

func find(dp [][]*Interval, value *Interval, index int) bool {
	for i := index - 2; i >= 0; i-- {
		ind := binarySearch(dp[i], value.l)
		if ind < 0 {
			ind = ^ind - 1
			if ind > 0 && dp[i][ind].r >= value.r {
				return true
			}
		} else {
			if dp[i][ind].r >= value.r {
				return true
			}
		}
	}
	return false
}

func solve() {
	n := next()
	k := next()

	l := make([]int, k)
	r := make([]int, k)
	for i := 0; i < k; i++ {
		l[i] = next()
		r[i] = next()
	}

	size := 2*k + 1
	dp := make([][]*Interval, size)
	for i := range dp {
		dp[i] = []*Interval{}
	}
	dp[0] = append(dp[0], &Interval{0, 0})

	prev := 0
	for i := 0; i < k; i++ {
		nxt := make([][]*Interval, size)
		for ii := range nxt {
			nxt[ii] = []*Interval{}
		}

		delta := l[i] - prev
		for index := 0; index < size; index++ {
			if index%2 == 0 {
				for _, interval := range dp[index] {
					interval.l += delta
					interval.r += delta
				}
			}
		}
		delta = r[i] - l[i]
		for ii := 0; ii < size; ii++ {
			if ii%2 == 0 {
				for _, interval := range dp[ii] {
					nxt[ii] = append(nxt[ii], &Interval{interval.l + delta, interval.r + delta})
					nxt[ii+1] = append(nxt[ii+1], &Interval{interval.l, interval.r + delta})
					nxt[ii+2] = append(nxt[ii+2], &Interval{interval.l, interval.r + delta})
				}
			} else {
				for _, interval := range dp[ii] {
					nxt[ii] = append(nxt[ii], &Interval{interval.l, interval.r})
					nxt[ii+1] = append(nxt[ii+1], &Interval{interval.l, interval.r + delta})
					nxt[ii+2] = append(nxt[ii+2], &Interval{interval.l, interval.r + delta})
				}
			}
		}

		prev = r[i]
		for index := 0; index < size; index++ {
			dp[index] = dp[index][:0]

			var pr *Interval = nil
			sorted := make([]*Interval, len(nxt[index]))
			copy(sorted, nxt[index])
			sort.Slice(sorted, func(a, b int) bool {
				return sorted[a].l < sorted[b].l
			})
			for _, interval := range sorted {
				if interval.l > n {
					break
				}
				if pr != nil && pr.r >= interval.l {
					if interval.r > pr.r {
						pr.r = interval.r
					}
				} else {
					if pr != nil && !find(dp, pr, index) {
						dp[index] = append(dp[index], pr)
					}
					pr = interval
				}
			}
			if pr != nil && !find(dp, pr, index) {
				dp[index] = append(dp[index], pr)
			}
		}
	}

	{
		delta := 2*n - prev
		for index := 0; index < size; index++ {
			if index%2 == 0 {
				for _, interval := range dp[index] {
					interval.l += delta
					interval.r += delta
				}
			}
		}
	}

	for i := 0; i < size; i++ {
		for _, interval := range dp[i] {
			if interval.l <= n && interval.r >= n {
				fmt.Fprintln(writer, "Full")
				fmt.Fprintln(writer, i)
				return
			}
		}
	}

	fmt.Fprintln(writer, "Hungry")
}

func main() {
	reader = bufio.NewReaderSize(os.Stdin, 1024*10)
	writer = bufio.NewWriterSize(os.Stdout, 1024*10)
	defer writer.Flush()
	solve()
}
